        return 2
    except FileProblem as exc:
        say("stockroom: %s\n" % exc)
        return 2
    except DataProblem as exc:
        say("stockroom: %s\n" % exc)
        return 1
    except Refusal as exc:
        say("stockroom: %s\n" % exc)
        return 1
    emit(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())

