"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys

from . import orders as orders_mod
from . import shelves
from .errors import ParseError, Refusal
from .model import Movement
from .parsing import (
    ORDER_ID_RE,
    SKU_RE,
    UINT_RE,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
)

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND ...
  stock [--json]                    history SKU [--json]
  low [--json]                      receive DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]              ship DATE SKU QUANTITY [NOTE]
  invoice ORDER [--json]            fulfil ORDER DATE
  report [--format text|csv|json]
"""

# command -> (positional counts allowed, takes --json, takes --format)
COMMANDS = {
    "stock": ((0,), True, False),
    "low": ((0,), True, False),
    "history": ((1,), True, False),
    "receive": ((3, 4), False, False),
    "ship": ((3, 4), False, False),
    "quote": ((1,), True, False),
    "fulfil": ((2,), False, False),
    "invoice": ((1,), True, False),
    "report": ((0,), False, True),
}
FREE_FORM = ("receive", "ship", "fulfil")
FILES_NEEDED = {
    "stock": (CATALOG, MOVEMENTS),
    "low": (CATALOG, MOVEMENTS),
    "history": (CATALOG, MOVEMENTS),
    "receive": (CATALOG, MOVEMENTS),
    "ship": (CATALOG, MOVEMENTS),
    "quote": (CATALOG, ORDERS),
    "fulfil": (CATALOG, MOVEMENTS, ORDERS),
    "invoice": (CATALOG, MOVEMENTS, ORDERS),
    "report": (CATALOG, MOVEMENTS, ORDERS),
}


class UsageError(Exception):
    """Something is wrong with the command line (exit 2)."""


class FileProblem(Exception):
    """A file cannot be read (exit 2)."""


class DataProblem(Exception):
    """A mistake in a data file (exit 1)."""


class Request(object):
    def __init__(self):
        self.directory = "."
        self.command = None
        self.json = False
        self.format = "text"
        self.args = []


def parse_command_line(argv):
    req = Request()
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a value")
            req.directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            req.directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1

    index = None
    for n, arg in enumerate(rest):
        if arg == "-" or not arg.startswith("-"):
            index = n
            break
    if index is None:
        raise UsageError("no command given")
    command = rest[index]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    counts, takes_json, takes_format = COMMANDS[command]
    req.command = command
    before, after = rest[:index], rest[index + 1:]

    if command in FREE_FORM:
        if before:
            raise UsageError("unknown option %r" % before[0])
        positional = after
    else:
        positional = []
        args = before + after
        j = 0
        while j < len(args):
            arg = args[j]
            if arg == "--json" and takes_json:
                req.json = True
            elif arg == "--format" and takes_format:
                if j + 1 >= len(args):
                    raise UsageError("--format needs a value")
                req.format = args[j + 1]
                j += 1
            elif arg.startswith("--format=") and takes_format:
                req.format = arg[len("--format="):]
            elif arg.startswith("-") and arg != "-":
                raise UsageError("unknown option %r" % arg)
            else:
                positional.append(arg)
            j += 1
        if req.format not in ("text", "csv", "json"):
            raise UsageError("bad --format value %r (text, csv or json)" % req.format)

    if len(positional) not in counts:
        raise UsageError(
            "wrong number of arguments for %s (got %d)" % (command, len(positional))
        )
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise UsageError("bad date %r (expected YYYY-MM-DD)" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise UsageError("bad date %r (expected YYYY-MM-DD)" % positional[1])
    req.args = positional
    return req


def read_text(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if os.path.isdir(directory) and not required:
            return ""
        raise FileProblem("%s: file not found" % name)
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name)


def parse_file(name, parser, *args):
    try:
        return parser(*args)
    except ParseError as exc:
        raise DataProblem("%s: %s" % (name, exc))


def load(req):
    """Read the needed files (catalogue first), then parse them in order."""
    if not os.path.isdir(req.directory):
        raise FileProblem("%s: not a directory" % req.directory)
    needed = FILES_NEEDED[req.command]
    texts = {}
    for name in needed:
        texts[name] = read_text(req.directory, name, name == CATALOG)
    catalog = parse_file(CATALOG, parse_catalog, texts[CATALOG])
    movements = orders = None
    if MOVEMENTS in texts:
        movements = parse_file(MOVEMENTS, parse_movements, texts[MOVEMENTS], catalog)
    if ORDERS in texts:
        orders = parse_file(ORDERS, parse_orders, texts[ORDERS], catalog)
    return catalog, movements, orders


# ---------------------------------------------------------------- output


def money(value):
    if value == 0:
        return "0.00"
    return format(value, "f")


def dump_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_text(lines):
    return "".join(line + "\n" for line in lines)


def find_order(orders, text):
    if not ORDER_ID_RE.fullmatch(text):
        raise Refusal("%r is not an order number" % text)
    wanted = text.upper()
    for order in orders:
        if order.id == wanted:
            return order
    raise Refusal("order %s is not in %s" % (wanted, ORDERS))


def quote_output(header, order, quote, as_json):
    if as_json:
        return dump_json(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "lines": [
                    {
                        "sku": l.sku,
                        "quantity": l.quantity,
                        "unit": money(l.unit),
                        "gross": money(l.gross),
                        "discount": money(l.discount),
                        "net": money(l.net),
                    }
                    for l in quote.lines
                ],
                "subtotal": money(quote.subtotal),
                "order_discount": money(quote.order_discount),
                "tax": money(quote.tax),
                "total": money(quote.total),
            }
        )
    out = [header]
    for l in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (l.sku, l.quantity, money(l.unit), money(l.gross), money(l.discount), money(l.net))
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_text(out)


def header_for(order, prefix=""):
    return "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)


def append_movements(directory, new):
    """Append the movements as one write, adding a newline first if needed."""
    path = os.path.join(directory, MOVEMENTS)
    text = "".join(shelves.format_movement(m) + "\n" for m in new)
    try:
        data = text.encode("utf-8")
    except UnicodeEncodeError:
        raise Refusal("note cannot be written as UTF-8")
    try:
        with open(path, "ab") as handle:
            size = handle.seek(0, os.SEEK_END)
            if size > 0:
                with open(path, "rb") as reader:
                    reader.seek(size - 1)
                    if reader.read(1) != b"\n":
                        data = b"\n" + data
            handle.write(data)
    except OSError as exc:
        raise FileProblem("%s: %s" % (MOVEMENTS, exc.strerror or exc))


def run_shelf_move(req, catalog, movements, sign):
    date_text, sku_text, qty_text = req.args[:3]
    note = req.args[3] if len(req.args) == 4 else ""
    if not SKU_RE.fullmatch(sku_text):
        raise Refusal("%r is not a SKU" % sku_text)
    sku = sku_text.upper()
    if sku not in catalog:
        raise Refusal("SKU %s is not in the catalogue" % sku)
    if not UINT_RE.fullmatch(qty_text) or int(qty_text) < 1:
        raise Refusal("quantity must be a whole number of 1 or more, got %r" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refusal("a note may not contain a line break")
    new = Movement(parse_date(date_text), sku, sign * int(qty_text), note.strip())
    shelves.check_append(movements, [new])
    append_movements(req.directory, [new])
    return shelves.format_movement(new) + "\n"


def run_fulfil(req, catalog, movements, orders):
    order = find_order(orders, req.args[0])
    date = parse_date(req.args[1])
    plan = orders_mod.plan_fulfil(order, movements, date)
    new = [
        Movement(date, sku, -ship, orders_mod.order_note(order.id))
        for sku, ship, _ in plan
        if ship > 0
    ]
    shelves.check_append(movements, new)
    before = orders_mod.shipped_so_far(order, movements)
    after = [b + ship for b, (_, ship, _) in zip(before, plan)]
    out = ["%s shipped %d backordered %d" % (sku, ship, left) for sku, ship, left in plan]
    out.append("status " + orders_mod.order_status(order, after))
    if new:
        append_movements(req.directory, new)
    return lines_text(out)


def run_report(req, catalog, movements, orders):
    rows = orders_mod.report_rows(orders, catalog, movements)
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if req.format == "json":
        return dump_json(rows)
    if req.format == "csv":
        buf = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buf.getvalue()
    return lines_text(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"], r["date"], r["customer"], r["status"],
            r["shipped"], r["ordered"], r["quoted"], r["invoiced"],
        )
        for r in rows
    )


def execute(req, catalog, movements, orders):
    cmd = req.command
    if cmd == "stock":
        rows = shelves.stock_rows(catalog, movements)
        if req.json:
            return dump_json(
                [
                    {"sku": p.sku, "name": p.name, "onhand": onhand, "status": st}
                    for p, onhand, st in rows
                ]
            )
        return lines_text("%s %d %s %s" % (p.sku, onhand, st, p.name) for p, onhand, st in rows)
    if cmd == "low":
        rows = shelves.low_rows(catalog, movements)
        if req.json:
            return dump_json(
                [
                    {"sku": p.sku, "onhand": onhand, "reorder": p.reorder, "buy": buy}
                    for p, onhand, buy in rows
                ]
            )
        return lines_text(
            "%s %d %d %d" % (p.sku, onhand, p.reorder, buy) for p, onhand, buy in rows
        )
    if cmd == "history":
        if not SKU_RE.fullmatch(req.args[0]) or req.args[0].upper() not in catalog:
            raise Refusal("SKU %s is not in the catalogue" % req.args[0].upper())
        rows = shelves.history_rows(req.args[0].upper(), movements)
        if req.json:
            return dump_json(
                [
                    {
                        "date": m.date.isoformat(),
                        "delta": shelves.signed(m.quantity),
                        "balance": balance,
                        "note": m.note,
                    }
                    for m, balance in rows
                ]
            )
        out = []
        for m, balance in rows:
            text = "%s %s %d" % (m.date.isoformat(), shelves.signed(m.quantity), balance)
            if m.note:
                text += " " + m.note
            out.append(text)
        return lines_text(out)
    if cmd == "receive":
        return run_shelf_move(req, catalog, movements, 1)
    if cmd == "ship":
        return run_shelf_move(req, catalog, movements, -1)
    if cmd == "quote":
        order = find_order(orders, req.args[0])
        quote = orders_mod.price_order(order, catalog)
        return quote_output(header_for(order), order, quote, req.json)
    if cmd == "invoice":
        order = find_order(orders, req.args[0])
        shipped = orders_mod.invoice_order(order, movements)
        if shipped is None:
            raise Refusal("nothing has shipped for %s" % order.id)
        quote = orders_mod.price_order(shipped, catalog)
        return quote_output(header_for(order, "invoice "), order, quote, req.json)
    if cmd == "fulfil":
        return run_fulfil(req, catalog, movements, orders)
    return run_report(req, catalog, movements, orders)


def say(message):
    try:
        sys.stderr.write(message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def emit(text):
    """Write stdout in one go; a closed pipe just stops quietly."""
    if not text:
        return
    try:
        sys.stdout.flush()
        sys.stdout.buffer.write(text.encode("utf-8", "replace"))
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError):
            pass


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        req = parse_command_line(list(argv))
        catalog, movements, orders = load(req)
        text = execute(req, catalog, movements, orders)
    except UsageError as exc:
        say("stockroom: %s\n%s" % (exc, USAGE))
        return 2
    except FileProblem as exc:
        say("stockroom: %s\n" % exc)
        return 2
    except DataProblem as exc:
        say("stockroom: %s\n" % exc)
        return 1
    except Refusal as exc:
        say("stockroom: %s\n" % exc)
        return 1
    emit(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())

