    wanted = text.upper()
    for order in orders:
        if order.id == wanted:
            return order
    raise Refusal("order %s is not in %s" % (wanted, ORDERS))


def quote_output(header, order, quote, as_json):
    if as_json:
        return dump_json(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "lines": [
                    {
                        "sku": l.sku,
                        "quantity": l.quantity,
                        "unit": money(l.unit),
                        "gross": money(l.gross),
                        "discount": money(l.discount),
                        "net": money(l.net),
                    }
                    for l in quote.lines
                ],
                "subtotal": money(quote.subtotal),
                "order_discount": money(quote.order_discount),
                "tax": money(quote.tax),
                "total": money(quote.total),
            }
        )
    out = [header]
    for l in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (l.sku, l.quantity, money(l.unit), money(l.gross), money(l.discount), money(l.net))
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_text(out)


def header_for(order, prefix=""):
    return "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)


def append_movements(directory, new):
    """Append the movements as one write, adding a newline first if needed."""
    path = os.path.join(directory, MOVEMENTS)
    text = "".join(shelves.format_movement(m) + "\n" for m in new)
    try:
        data = text.encode("utf-8")
    except UnicodeEncodeError:
        raise Refusal("note cannot be written as UTF-8")
    try:
        with open(path, "ab") as handle:
            size = handle.seek(0, os.SEEK_END)
            if size > 0:
                with open(path, "rb") as reader:
                    reader.seek(size - 1)
                    if reader.read(1) != b"\n":
                        data = b"\n" + data
            handle.write(data)
    except OSError as exc:
        raise FileProblem("%s: %s" % (MOVEMENTS, exc.strerror or exc))


def run_shelf_move(req, catalog, movements, sign):
    date_text, sku_text, qty_text = req.args[:3]
    note = req.args[3] if len(req.args) == 4 else ""
    if not SKU_RE.fullmatch(sku_text):
        raise Refusal("%r is not a SKU" % sku_text)
    sku = sku_text.upper()
    if sku not in catalog:
        raise Refusal("SKU %s is not in the catalogue" % sku)
    if not UINT_RE.fullmatch(qty_text) or int(qty_text) < 1:
        raise Refusal("quantity must be a whole number of 1 or more, got %r" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refusal("a note may not contain a line break")
    new = Movement(parse_date(date_text), sku, sign * int(qty_text), note.strip())
    shelves.check_append(movements, [new])
    append_movements(req.directory, [new])
    return shelves.format_movement(new) + "\n"


def run_fulfil(req, catalog, movements, orders):
    order = find_order(orders, req.args[0])
    date = parse_date(req.args[1])
    plan = orders_mod.plan_fulfil(order, movements, date)
    new = [
        Movement(date, sku, -ship, orders_mod.order_note(order.id))
        for sku, ship, _ in plan
        if ship > 0
    ]
    shelves.check_append(movements, new)
    before = orders_mod.shipped_so_far(order, movements)
    after = [b + ship for b, (_, ship, _) in zip(before, plan)]
    out = ["%s shipped %d backordered %d" % (sku, ship, left) for sku, ship, left in plan]
    out.append("status " + orders_mod.order_status(order, after))
    if new:
        append_movements(req.directory, new)
    return lines_text(out)


def run_report(req, catalog, movements, orders):
    rows = orders_mod.report_rows(orders, catalog, movements)
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if req.format == "json":
        return dump_json(rows)
    if req.format == "csv":
        buf = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buf.getvalue()
    return lines_text(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"], r["date"], r["customer"], r["status"],
            r["shipped"], r["ordered"], r["quoted"], r["invoiced"],
        )
        for r in rows
    )


def execute(req, catalog, movements, orders):
    cmd = req.command
    if cmd == "stock":
        rows = shelves.stock_rows(catalog, movements)
        if req.json:
            return dump_json(
                [
                    {"sku": p.sku, "name": p.name, "onhand": onhand, "status": st}
                    for p, onhand, st in rows
                ]
            )
        return lines_text("%s %d %s %s" % (p.sku, onhand, st, p.name) for p, onhand, st in rows)
    if cmd == "low":
        rows = shelves.low_rows(catalog, movements)
        if req.json:
            return dump_json(
                [
                    {"sku": p.sku, "onhand": onhand, "reorder": p.reorder, "buy": buy}
                    for p, onhand, buy in rows
                ]
            )
        return lines_text(
            "%s %d %d %d" % (p.sku, onhand, p.reorder, buy) for p, onhand, buy in rows
        )
    if cmd == "history":
        if not SKU_RE.fullmatch(req.args[0]) or req.args[0].upper() not in catalog:
            raise Refusal("SKU %s is not in the catalogue" % req.args[0].upper())
        rows = shelves.history_rows(req.args[0].upper(), movements)
        if req.json:
            return dump_json(
                [
                    {
                        "date": m.date.isoformat(),
                        "delta": shelves.signed(m.quantity),
                        "balance": balance,
                        "note": m.note,
                    }
                    for m, balance in rows
                ]
            )
        out = []
        for m, balance in rows:
            text = "%s %s %d" % (m.date.isoformat(), shelves.signed(m.quantity), balance)
            if m.note:
                text += " " + m.note
            out.append(text)
        return lines_text(out)
    if cmd == "receive":
        return run_shelf_move(req, catalog, movements, 1)
    if cmd == "ship":
        return run_shelf_move(req, catalog, movements, -1)
    if cmd == "quote":
        order = find_order(orders, req.args[0])
        quote = orders_mod.price_order(order, catalog)
        return quote_output(header_for(order), order, quote, req.json)
    if cmd == "invoice":
        order = find_order(orders, req.args[0])
        shipped = orders_mod.invoice_order(order, movements)
        if shipped is None:
            raise Refusal("nothing has shipped for %s" % order.id)
        quote = orders_mod.price_order(shipped, catalog)
        return quote_output(header_for(order, "invoice "), order, quote, req.json)
    if cmd == "fulfil":
        return run_fulfil(req, catalog, movements, orders)
    return run_report(req, catalog, movements, orders)


def say(message):
    try:
        sys.stderr.write(message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def emit(text):
    """Write stdout in one go; a closed pipe just stops quietly."""
    if not text:
        return
    try:
        sys.stdout.flush()
        sys.stdout.buffer.write(text.encode("utf-8", "replace"))
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError):
            pass


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        req = parse_command_line(list(argv))
        catalog, movements, orders = load(req)
        text = execute(req, catalog, movements, orders)
    except UsageError as exc:
        say("stockroom: %s\n%s" % (exc, USAGE))
        return 2
    except FileProblem as exc:
        say("stockroom: %s\n" % exc)
        return 2
    except DataProblem as exc:
        say("stockroom: %s\n" % exc)
        return 1
    except Refusal as exc:
        say("stockroom: %s\n" % exc)
        return 1
    emit(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
